describe('Cookie Consent Banner - Accept Button', () => {
  beforeEach(() => {
    cy.visit('/cookie-consent');
  });

  it('should hide the cookie consent banner after user accepts', () => {
    // Verify banner is visible
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible');
    cy.get('[data-testid="cookie-consent-title"]').should('contain', 'Cookie Consent');
    cy.get('[data-testid="accept-button"]').should('be.visible');

    // User accepts cookies
    cy.get('[data-testid="accept-button"]').click();

    // Verify banner is hidden
    cy.get('[data-testid="cookie-consent-banner"]').should('not.exist');

    // Verify acceptance cookie is set
    cy.getCookie('cookie-consent-accepted').should('exist');
    cy.getCookie('cookie-consent-accepted').should('have.value', 'true');

    // Verify user can interact with page content
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="main-content"]').should('contain', 'Welcome');
  });

  it('should not hide banner if user clicks cancel or ignores it', () => {
    // Verify banner is visible
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible');
    cy.get('[data-testid="accept-button"]').should('be.visible');
    cy.get('[data-testid="cancel-button"]').should('be.visible');

    // User clicks cancel
    cy.get('[data-testid="cancel-button"]').click();

    // Verify banner is still visible
    cy.get('[data-testid="cookie-consent-banner"]').should('be.visible');
    cy.get('[data-testid="cookie-consent-title"]').should('contain', 'Cookie Consent');

    // Verify acceptance cookie is NOT set
    cy.getCookie('cookie-consent-accepted').should('not.exist');

    // Verify user can still interact with page content, but banner remains
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="main-content"]').should('contain', 'Welcome');

    // Verify banner is still dismissible
    cy.get('[data-testid="accept-button"]').should('be.visible');
  });
});
